-- generated by `draftpaper apply` ({{label}}): the colorscheme "draftpaper"
-- colorscheme "draftpaper": {{label}}
vim.cmd.highlight("clear")
if vim.fn.exists("syntax_on") == 1 then vim.cmd.syntax("reset") end
vim.o.termguicolors = true
vim.o.background = "{{variant}}"
vim.g.colors_name = "draftpaper"

local p = {
  bg = "{{term_bg}}", bg_alt = "{{term_bg_alt}}", fg = "{{term_fg}}",
  dim = "{{br_black}}", chrome = "{{bg_alt}}", chrome_fg = "{{fg}}",
  surface = "{{surface_alt}}", border = "{{border}}",
  accent = "{{accent}}", on_accent = "{{on_accent}}", sel_bg = "{{sel_bg}}", sel_fg = "{{sel_fg}}",
  red = "{{red}}", green = "{{green}}", yellow = "{{yellow}}", blue = "{{blue}}",
  magenta = "{{magenta}}", cyan = "{{cyan}}", white = "{{white}}",
  br_red = "{{br_red}}", br_green = "{{br_green}}", br_yellow = "{{br_yellow}}", br_blue = "{{br_blue}}",
  br_magenta = "{{br_magenta}}", br_cyan = "{{br_cyan}}", br_white = "{{br_white}}",
}
local function hi(group, spec) vim.api.nvim_set_hl(0, group, spec) end
local function link(group, to) vim.api.nvim_set_hl(0, group, { link = to }) end

-- editor chrome
hi("Normal",        { fg = p.fg, bg = p.bg })
hi("NormalFloat",   { fg = p.chrome_fg, bg = p.surface })
hi("FloatBorder",   { fg = p.border, bg = p.surface })
hi("NormalNC",      { fg = p.fg, bg = p.bg })
hi("Cursor",        { fg = p.on_accent, bg = p.accent })
hi("CursorLine",    { bg = p.bg_alt })
hi("CursorColumn",  { bg = p.bg_alt })
hi("ColorColumn",   { bg = p.bg_alt })
hi("LineNr",        { fg = p.dim })
hi("CursorLineNr",  { fg = p.accent, bold = true })
hi("SignColumn",    { bg = p.bg })
hi("FoldColumn",    { fg = p.dim, bg = p.bg })
hi("Folded",        { fg = p.dim, bg = p.bg_alt })
hi("VertSplit",     { fg = p.border, bg = p.bg })
hi("WinSeparator",  { fg = p.border, bg = p.bg })
hi("StatusLine",    { fg = p.chrome_fg, bg = p.chrome })
hi("StatusLineNC",  { fg = p.dim, bg = p.bg_alt })
hi("TabLine",       { fg = p.chrome_fg, bg = p.chrome })
hi("TabLineFill",   { bg = p.chrome })
hi("TabLineSel",    { fg = p.on_accent, bg = p.accent, bold = true })
hi("WildMenu",      { fg = p.on_accent, bg = p.accent })
hi("Pmenu",         { fg = p.chrome_fg, bg = p.surface })
hi("PmenuSel",      { fg = p.sel_fg, bg = p.sel_bg })
hi("PmenuSbar",     { bg = p.surface })
hi("PmenuThumb",    { bg = p.border })
hi("Visual",        { fg = p.sel_fg, bg = p.sel_bg })
hi("VisualNOS",     { fg = p.sel_fg, bg = p.sel_bg })
hi("Search",        { fg = p.on_accent, bg = p.accent })
hi("IncSearch",     { fg = p.on_accent, bg = p.br_yellow })
hi("CurSearch",     { fg = p.on_accent, bg = p.br_yellow })
hi("MatchParen",    { fg = p.accent, bold = true, underline = true })
hi("NonText",       { fg = p.dim })
hi("Whitespace",    { fg = p.dim })
hi("SpecialKey",    { fg = p.dim })
hi("EndOfBuffer",   { fg = p.bg })
hi("Title",         { fg = p.accent, bold = true })
hi("Directory",     { fg = p.br_blue })
hi("ModeMsg",       { fg = p.accent, bold = true })
hi("MoreMsg",       { fg = p.br_green })
hi("Question",      { fg = p.br_green })
hi("ErrorMsg",      { fg = p.br_red, bold = true })
hi("WarningMsg",    { fg = p.br_yellow })
hi("QuickFixLine",  { bg = p.bg_alt })
hi("Conceal",       { fg = p.dim })
hi("SpellBad",      { sp = p.br_red, undercurl = true })
hi("SpellCap",      { sp = p.br_blue, undercurl = true })
hi("SpellRare",     { sp = p.br_magenta, undercurl = true })
hi("SpellLocal",    { sp = p.br_cyan, undercurl = true })

-- syntax
hi("Comment",       { fg = p.dim, italic = true })
hi("Constant",      { fg = p.br_magenta })
hi("String",        { fg = p.green })
hi("Character",     { fg = p.green })
hi("Number",        { fg = p.br_magenta })
hi("Boolean",       { fg = p.br_magenta })
hi("Float",         { fg = p.br_magenta })
hi("Identifier",    { fg = p.fg })
hi("Function",      { fg = p.br_blue })
hi("Statement",     { fg = p.yellow })
hi("Keyword",       { fg = p.yellow })
hi("Conditional",   { fg = p.yellow })
hi("Repeat",        { fg = p.yellow })
hi("Label",         { fg = p.yellow })
hi("Operator",      { fg = p.fg })
hi("Exception",     { fg = p.red })
hi("PreProc",       { fg = p.red })
hi("Include",       { fg = p.red })
hi("Define",        { fg = p.red })
hi("Macro",         { fg = p.red })
hi("Type",          { fg = p.cyan })
hi("StorageClass",  { fg = p.cyan })
hi("Structure",     { fg = p.cyan })
hi("Typedef",       { fg = p.cyan })
hi("Special",       { fg = p.br_cyan })
hi("SpecialChar",   { fg = p.br_cyan })
hi("Delimiter",     { fg = p.fg })
hi("SpecialComment",{ fg = p.dim, bold = true })
hi("Debug",         { fg = p.red })
hi("Underlined",    { fg = p.br_blue, underline = true })
hi("Error",         { fg = p.br_red, bold = true })
hi("Todo",          { fg = p.on_accent, bg = p.accent, bold = true })
hi("Added",         { fg = p.green })
hi("Changed",       { fg = p.yellow })
hi("Removed",       { fg = p.red })

-- diff
hi("DiffAdd",       { bg = p.bg_alt, fg = p.br_green })
hi("DiffChange",    { bg = p.bg_alt })
hi("DiffDelete",    { bg = p.bg_alt, fg = p.br_red })
hi("DiffText",      { bg = p.bg_alt, fg = p.br_yellow, bold = true })
hi("diffAdded",     { fg = p.green })
hi("diffRemoved",   { fg = p.red })
hi("diffChanged",   { fg = p.yellow })

-- diagnostics / lsp
hi("DiagnosticError", { fg = p.br_red })
hi("DiagnosticWarn",  { fg = p.br_yellow })
hi("DiagnosticInfo",  { fg = p.br_blue })
hi("DiagnosticHint",  { fg = p.br_cyan })
hi("DiagnosticUnderlineError", { sp = p.br_red, undercurl = true })
hi("DiagnosticUnderlineWarn",  { sp = p.br_yellow, undercurl = true })
hi("DiagnosticUnderlineInfo",  { sp = p.br_blue, undercurl = true })
hi("DiagnosticUnderlineHint",  { sp = p.br_cyan, undercurl = true })
hi("LspReferenceText",  { bg = p.bg_alt })
hi("LspReferenceRead",  { bg = p.bg_alt })
hi("LspReferenceWrite", { bg = p.bg_alt, underline = true })

-- treesitter / semantic
link("@variable", "Identifier")
link("@variable.builtin", "Special")
link("@variable.parameter", "Identifier")
link("@variable.member", "Identifier")
link("@constant", "Constant")
link("@constant.builtin", "Constant")
link("@module", "Type")
link("@string", "String")
link("@string.escape", "SpecialChar")
link("@string.regexp", "SpecialChar")
link("@character", "Character")
link("@number", "Number")
link("@boolean", "Boolean")
link("@type", "Type")
link("@type.builtin", "Type")
link("@attribute", "PreProc")
link("@property", "Identifier")
link("@function", "Function")
link("@function.builtin", "Special")
link("@function.macro", "Macro")
link("@constructor", "Type")
link("@operator", "Operator")
link("@keyword", "Keyword")
link("@keyword.import", "Include")
link("@keyword.return", "Keyword")
link("@punctuation", "Delimiter")
link("@comment", "Comment")
link("@markup.heading", "Title")
link("@markup.link", "Underlined")
link("@markup.raw", "String")
link("@tag", "Keyword")
link("@tag.attribute", "Identifier")
link("@tag.delimiter", "Delimiter")

